const cropKeys=['cropOpen','cropTitle','cropHelp','cropSource','cropReference','cropResult','cropStart','cropEnd','cropMotion','cropFocus','cropMove','cropCopy','cropSuggested','cropApply','cropCancel','cropPlay','cropStop','cropZoom','cropX','cropY','cropGrid','cropEnabled','cropView','compositionStale','compositionFocus','cropClear','cropBlocked','cropChanged','cropCamera','cropEmpty','cropSaved','cropNew','cropDismiss','cropCancelled'];
export function compositionLabels(lang){return Object.fromEntries(cropKeys.map((k,i)=>[k,(cropText[lang]||cropText.EN)[i]]));}
export function validateCompositionLabels(){return Object.values(cropText).every(values=>values.length===cropKeys.length&&values.every(v=>typeof v==='string'&&v));}
